-- Stage 6C: privacy-safe tour likes. Stable share links are generated by the visitor app.

create table public.tour_likes (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete restrict,
  tour_id uuid not null,
  user_id uuid not null references auth.users (id) on delete restrict,
  created_at timestamptz not null default now(),
  constraint tour_likes_tour_fk foreign key (organization_id, tour_id)
    references public.tours (organization_id, id) on delete cascade,
  constraint tour_likes_one_per_user unique (tour_id, user_id)
);

create index tour_likes_count_idx on public.tour_likes (tour_id);
create index tour_likes_user_idx on public.tour_likes (user_id, created_at desc);

create table public.tour_like_events (
  id bigint generated always as identity primary key,
  organization_id uuid not null references public.organizations (id) on delete restrict,
  tour_id uuid not null,
  user_id uuid not null references auth.users (id) on delete restrict,
  action text not null,
  created_at timestamptz not null default now(),
  constraint tour_like_events_tour_fk foreign key (organization_id, tour_id)
    references public.tours (organization_id, id) on delete restrict,
  constraint tour_like_events_action check (action in ('liked', 'unliked'))
);

create index tour_like_events_rate_idx on public.tour_like_events (user_id, created_at desc);

create trigger tour_like_events_append_only
before update or delete on public.tour_like_events
for each row execute function private.prevent_append_only_mutation();

create or replace function public.set_tour_like(p_tour_id uuid, p_liked boolean)
returns table (liked boolean, like_count bigint)
language plpgsql security definer set search_path = ''
as $$
declare
  v_actor uuid := auth.uid();
  v_organization_id uuid;
  v_current boolean;
begin
  perform private.require_active_rating_user(v_actor);
  if p_liked is null then raise exception 'Like state is required' using errcode = '22023'; end if;

  select organization_id into v_organization_id
  from public.tours where id = p_tour_id and status = 'published';
  if v_organization_id is null then raise exception 'Published tour not found' using errcode = '22023'; end if;
  if p_liked and private.is_community_banned(v_organization_id, v_actor) then
    raise exception 'Community submissions are currently disabled for this account' using errcode = '42501';
  end if;

  -- Serialize the same visitor/tour pair so concurrent taps cannot duplicate evidence.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_actor::text || ':' || p_tour_id::text, 0));

  select exists (
    select 1 from public.tour_likes where tour_id = p_tour_id and user_id = v_actor
  ) into v_current;

  if v_current is distinct from p_liked then
    if (select count(*) from public.tour_like_events where user_id = v_actor and created_at > now() - interval '1 minute') >= 10 then
      raise exception 'Too many like changes. Please wait before trying again.' using errcode = '42900';
    end if;
    if p_liked then
      insert into public.tour_likes (organization_id, tour_id, user_id)
      values (v_organization_id, p_tour_id, v_actor)
      on conflict (tour_id, user_id) do nothing;
    else
      delete from public.tour_likes where tour_id = p_tour_id and user_id = v_actor;
    end if;
    insert into public.tour_like_events (organization_id, tour_id, user_id, action)
    values (v_organization_id, p_tour_id, v_actor, case when p_liked then 'liked' else 'unliked' end);
  end if;

  return query select p_liked, count(*)::bigint from public.tour_likes where tour_id = p_tour_id;
end;
$$;

create or replace function public.get_tour_like_summary(p_tour_id uuid)
returns table (like_count bigint, viewer_liked boolean)
language sql stable security definer set search_path = ''
as $$
  select
    (select count(*)::bigint from public.tour_likes l where l.tour_id = p_tour_id),
    case when auth.uid() is null then false else exists (
      select 1 from public.tour_likes l where l.tour_id = p_tour_id and l.user_id = auth.uid()
    ) end
  from public.tours t
  join public.organizations o on o.id = t.organization_id
  where t.id = p_tour_id and t.status = 'published' and o.status in ('active', 'trial');
$$;

alter table public.tour_likes enable row level security;
alter table public.tour_like_events enable row level security;

create policy tour_likes_select_own on public.tour_likes for select to authenticated
using (user_id = (select auth.uid()));
create policy tour_like_events_select_own_or_admin on public.tour_like_events for select to authenticated
using (
  user_id = (select auth.uid())
  or (select private.is_super_admin())
  or (select private.has_org_role(organization_id, array['administrator'::public.organization_role]))
);

revoke all on public.tour_likes, public.tour_like_events from anon, authenticated;
grant select on public.tour_likes, public.tour_like_events to authenticated;
revoke all on function public.set_tour_like(uuid, boolean) from public, anon;
grant execute on function public.set_tour_like(uuid, boolean) to authenticated;
grant execute on function public.get_tour_like_summary(uuid) to anon, authenticated;

comment on table public.tour_likes is 'One current private like per verified visitor and published tour.';
comment on table public.tour_like_events is 'Append-only private like/unlike changes used for abuse throttling and audit evidence.';
comment on function public.get_tour_like_summary(uuid) is 'Returns a public aggregate count and only the current caller own like state.';
